DEFAULT_CONFIG = {
    "rsi_adequado": 0.50,
    "rsi_atencao": 0.45,
    "cmj_atencao": -5.0,
    "cmj_atencao_elevada": -8.0,
    "clube_nome": "BOAVISTA S.C SAF",
    "clube_subtitulo": "NÚCLEO DE SAÚDE & PERFORMANCE",
}


def load_config():
    cfg = dict(DEFAULT_CONFIG)
    if CONFIG_PATH.exists():
        try:
            cfg.update(json.loads(CONFIG_PATH.read_text(encoding="utf-8")))
        except Exception:
            pass
    return cfg


def save_config(cfg):
    DB.mkdir(parents=True, exist_ok=True)
    CONFIG_PATH.write_text(json.dumps(cfg, indent=2, ensure_ascii=False), encoding="utf-8")


