@st.cache_data
def load_exports():
    frames=[]
    if INPUT.exists():
        for f in sorted(INPUT.glob("*.csv")):
            try:
                x=pd.read_csv(f)
                x.columns=[c.strip() for c in x.columns]
                x["Arquivo"]=f.name
                frames.append(x)
            except Exception:
                pass
    if not frames:
        return pd.DataFrame()
    d=pd.concat(frames,ignore_index=True)
    name=next((c for c in d.columns if c.lower()=="name"),None)
    date_col=next((c for c in d.columns if c.lower()=="date"),None)
    cmj=next((c for c in d.columns if "jump height" in c.lower()),None)
    rsi=next((c for c in d.columns if any(k in c.strip().lower() for k in ["rsi", "reactive strength index"])),None)
    if not all([name,date_col,cmj]):
        return pd.DataFrame()
    d["Atleta"]=d[name].astype(str).str.strip()
    d["Data"]=pd.to_datetime(d[date_col],dayfirst=True,errors="coerce")
    d["CMJ"]=pd.to_numeric(d[cmj],errors="coerce")
    d["RSI"]=pd.to_numeric(d[rsi],errors="coerce") if rsi else np.nan
    d=d.dropna(subset=["Atleta","Data","CMJ"]).copy()
    d["Data_dia"]=d["Data"].dt.date
    return d.sort_values(["Atleta","Data"])

@st.cache_data
def load_registry():
    f=DB/"cadastro_atletas.csv"
    if not f.exists():
        return pd.DataFrame(columns=["Name","ExternalId","Posição","Grupo","Ativo"])
    return pd.read_csv(f,dtype=str).fillna("")

d=load_exports()
reg=load_registry()
if d.empty:
    st.error("Nenhum CSV válido foi encontrado em 01_ENTRADA.")
    st.stop()

d=d.merge(reg[["Name","Posição","Grupo","Ativo"]],left_on="Atleta",right_on="Name",how="left")
for c,default in [("Posição","Não cadastrada"),("Grupo","Não cadastrado"),("Ativo","Sim")]:
    d[c]=d[c].fillna(default).replace("",default)

g=d.groupby("Atleta",sort=False)
d["Último CMJ"]=g["CMJ"].shift(1)
d["Máximo histórico"]=g["CMJ"].cummax()

def best5(s):
    vals=[]; out=[]
    for v in s:
        vals.append(float(v)); out.append(np.mean(sorted(vals,reverse=True)[:5]))
    return pd.Series(out,index=s.index)

d["Baseline"]=g["CMJ"].transform(best5)
d["Δ% Último"]=(d["CMJ"]-d["Último CMJ"])/d["Último CMJ"]*100
d["Δ% Máximo"]=(d["CMJ"]-d["Máximo histórico"])/d["Máximo histórico"]*100
d["Δ% Baseline"]=(d["CMJ"]-d["Baseline"])/d["Baseline"]*100

last_day=d["Data_dia"].max()
today=d[d["Data_dia"]==last_day].copy()

stats=today.groupby("Posição")["CMJ"].agg(["mean","std"]).rename(columns={"mean":"Média posição","std":"DP posição"})
today=today.join(stats,on="Posição")
today["Z-score posição"]=(today["CMJ"]-today["Média posição"])/today["DP posição"].replace(0,np.nan)

def cmj_status(v):
    if pd.isna(v): return "Sem baseline"
    if v <= CFG["cmj_atencao_elevada"]: return "Atenção elevada"
    if v <= CFG["cmj_atencao"]: return "Atenção"
    return "Dentro do esperado"

def rsi_status(v):
    if pd.isna(v): return "Sem RSI"
    if v < CFG["rsi_atencao"]: return "Crítico"
    if v < CFG["rsi_adequado"]: return "Atenção"
    return "Adequado"

def rsi_badge(v):
    if pd.isna(v): return "⚪ Sem dado"
    if v < CFG["rsi_atencao"]: return "🔴 Crítico"
    if v < CFG["rsi_adequado"]: return "🟡 Atenção"
    return "🟢 Adequado"

today["Status"]=today["Δ% Baseline"].apply(cmj_status)
today["Status RSI"]=today["RSI"].apply(rsi_status)
today["RSI Classificação"]=today["RSI"].apply(rsi_badge)

