st.sidebar.markdown(f'<div class="sidebar-sub">{CFG["clube_subtitulo"]}</div>',unsafe_allow_html=True)
st.sidebar.markdown("---")

MODULES=["Dashboard","Ciência","Desempenho","Prevenção","Resultados","Atletas","Avaliações","Relatórios","Comparativos","Configurações"]
